/**
 * appendToFlowVariables
 * ---------------------
 * Type-only helper that appends element(s) to **array-typed** Flow variables while keeping full compile-time safety.
 *
 *
 * Rules:
 * - `definition` may be either the flow-execution ID (`Now.ID.…`) or the same ID wrapped in an object that also
 * carries an `annotation` string.
 * - `variables` is the schema returned by {@link FlowVariables}.
 * - Keys in `values` must reference array-typed variables — non-array targets are rejected at compile time.
 * - Each value can be a single element, an array of elements, or a string template compatible with the element type.
 *
 * This helper is erased at runtime – it only influences the TypeScript type-checker. The build plugin reads the AST to
 * emit the corresponding `sys_hub_flow_logic_instance_v2` record.
 *
 * @param definition  Flow execution identifier (+ optional annotation).
 * @param variables   Schema produced by {@link FlowVariables}.
 * @param values      Partial map keyed by array-typed variable names with the element(s) to append.
 */
import type { FlowVariableDefinition } from '../FlowVariables';
export declare function AppendToFlowVariables<T extends FlowVariableDefinition, V extends Record<string, unknown>, KV extends {
    [K in keyof V]?: V[K] extends Array<infer E> ? E | E[] | unknown[] | string : never;
}>(definition: T, variables: V, values: KV): {
    type: 'appendflowvariables';
};
